#!/bin/sh
set -eu
target_dir=/var/lib/docker/volumes/guoxue_h5_dist/_data/static/customer-service
target_file="$target_dir/wecom-qr.png"
mkdir -p "$target_dir"
tmp_file="$target_file.tmp.$$"
printf '%s' '' | base64 -d > "$tmp_file"
[ "$(sha256sum "$tmp_file" | awk '{print $1}')" = "a88cfa6426f3bdddeca712c2609e38e70b588adca63e1d350d6b9160e25e9629" ]
chmod 0644 "$tmp_file"
mv "$tmp_file" "$target_file"

docker exec -i guoxue-server node <<'NODE'
const { PrismaClient } = require('/app/apps/server/node_modules/@prisma/client');
const db = new PrismaClient();
(async () => {
  await db.$executeRawUnsafe('ALTER TABLE "BrandConfig" ADD COLUMN IF NOT EXISTS "serviceWechatQrUrl" TEXT NOT NULL DEFAULT \'\'');
  await db.$executeRawUnsafe(
    'UPDATE "BrandConfig" SET "serviceWechatQrUrl" = $1 WHERE "id" = $2',
    'https://api.rebugx.cn/h5/static/customer-service/wecom-qr.png',
    'default',
  );
  const rows = await db.$queryRawUnsafe('SELECT "id", "serviceWechatQrUrl" FROM "BrandConfig" WHERE "id" = $1', 'default');
  if (!rows.length || rows[0].serviceWechatQrUrl !== 'https://api.rebugx.cn/h5/static/customer-service/wecom-qr.png') {
    throw new Error('客服二维码配置写入校验失败');
  }
})().finally(() => db.$disconnect());
NODE

printf 'CUSTOMER_SERVICE_QR_CONFIGURED %s\n' "$(sha256sum "$target_file" | awk '{print $1}')"
